package com.bank.liquidation;

import java.util.Arrays;
import java.util.logging.Logger;

public class LiquidationOptimizer {

    private static final Logger log = Logger.getLogger(LiquidationOptimizer.class.getName());

    public int maxCoins(int[] values) {
        int n = values.length;
        int[] nums = new int[n + 2];                   // pad with 1 at both ends
        nums[0] = 1;
        nums[n + 1] = 1;
        for (int i = 0; i < n; i++) nums[i + 1] = values[i];
        int[][] dp = new int[n + 2][n + 2];
        for (int len = 2; len <= n + 1; len++) {       // open-interval length (i..j exclusive)
            for (int i = 0; i + len <= n + 1; i++) {
                int j = i + len;
                for (int k = i + 1; k < j; k++) {       // k = LAST balloon burst in (i,j)
                    int coins = dp[i][k] + nums[i] * nums[k] * nums[j] + dp[k][j];
                    dp[i][j] = Math.max(dp[i][j], coins);
                }
            }
        }
        int result = dp[0][n + 1];
        log.info(() -> "Max coins from bursting = " + result);
        return result;
    }
}
