package com.bank.liquidation;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

public class BurstBalloonsDemo {

    private static final Logger log = Logger.getLogger(BurstBalloonsDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — Liquidation Optimizer (Burst Balloons)");
        LiquidationOptimizer optimizer = new LiquidationOptimizer();
        log.info("{3,1,5,8} → " + optimizer.maxCoins(new int[]{3, 1, 5, 8})); // 167
        log.info("{1,5} → " + optimizer.maxCoins(new int[]{1, 5}));            // 10
    }
}
